steps.script:
var ov = tree.root.get_node("/root/TutorialOverlay")
InputDeviceManager.set_meta("t2w_formations_w", ov.card_blocker_rect().size.x)
InputDeviceManager.set_meta("t2w_formations_content", ov.card_content_width())
print("[T2W] formations blocker=", ov.card_blocker_rect(), " card=", ov.card_rect(), " content=", ov.card_content_width(), " placement=", ov.card_placement())
return ov.card_blocker_overlap()

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var q = [fd]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is OptionButton and nd.item_count > 0 and nd.get_item_text(0) == "(Unattached)":
		nd.select(1)
		nd.item_selected.emit(1)
		return true
	for c in nd.get_children():
		q.append(c)
return false

var ov = tree.root.get_node("/root/TutorialOverlay")
print("[T2W] after step change: card=", ov.card_rect(), " content=", ov.card_content_width(), " overlap=", ov.card_blocker_overlap())
return ov.card_blocker_overlap()

var fd = tree.root.get_node("/root/Main/FormationsDialog")
var q = [fd]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is CheckBox and str(nd.text).begins_with("Boyz") and not ("Reserves" in str(nd.text)):
		nd.button_pressed = true
		return true
	for c in nd.get_children():
		q.append(c)
return false

var ov = tree.root.get_node("/root/TutorialOverlay")
var b = ov.card_blocker_rect()
if b.size.x <= 0.0:
	return "no blocker"
print("[T2W] rolloff blocker=", b, " card=", ov.card_rect(), " content=", ov.card_content_width())
var was = float(InputDeviceManager.get_meta("t2w_formations_w"))
var vp = tree.root.get_visible_rect().size
var full_w = ov.CARD_CONTENT_WIDTH + ov.CARD_CHROME_W
var top_band = Rect2(Vector2(maxf((vp.x - full_w) * 0.5, 0.0), ov.CARD_TOP_OFFSET), Vector2(full_w, ov.card_rect().size.y))
if absf(b.size.x - was) <= 1.0:
	return "same width as formations (%.0f)" % was
return "bottom-docked" if not top_band.grow(ov.CARD_DIALOG_GAP).intersects(b) else "reaches top band"

var ov = tree.root.get_node("/root/TutorialOverlay")
var was = float(InputDeviceManager.get_meta("t2w_formations_content"))
var now = ov.card_content_width()
if absf(now - was) <= 1.0:
	return "latched at %.0f across two different dialogs" % now
return "widened" if now >= ov.CARD_CONTENT_WIDTH else "narrowed to %.0f" % now

var b = tree.root.get_node_or_null("/root/Main/RollOffDialog/Content/ButtonBar/RollButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var b = tree.root.get_node_or_null("/root/Main/RollOffDialog/Content/ButtonBar/RollButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
	return true
var q = [tree.root]
while not q.is_empty():
	var nd = q.pop_back()
	if nd is Button and nd.is_visible_in_tree() and "Re-roll" in str(nd.text):
		nd.pressed.emit()
		return true
	for c in nd.get_children():
		q.append(c)
return true

var b = tree.root.get_node_or_null("/root/Main/RollOffDialog/Content/ButtonBar/ContinueButton")
if b != null and b.is_visible_in_tree():
	b.pressed.emit()
return true

var ov = tree.root.get_node("/root/TutorialOverlay")
var b = ov.card_blocker_rect()
print("[T2W] no dialog: blocker=", b, " card=", ov.card_rect(), " content=", ov.card_content_width(), " placement=", ov.card_placement())
return b.size == Vector2.ZERO
